from pathlib import Path
import urllib.request

SAM_CHECKPOINTS = {
    "vit_b": ("sam_vit_b_01ec64.pth", "https://dl.fbaipublicfiles.com/segment_anything/sam_vit_b_01ec64.pth"),
    "vit_l": ("sam_vit_l_0b3195.pth", "https://dl.fbaipublicfiles.com/segment_anything/sam_vit_l_0b3195.pth"),
    "vit_h": ("sam_vit_h_4b8939.pth", "https://dl.fbaipublicfiles.com/segment_anything/sam_vit_h_4b8939.pth"),
}


def patch_segment_anything_float32():
    try:
        from copy import deepcopy
        import torch
        from segment_anything.utils.transforms import ResizeLongestSide
        from segment_anything.automatic_mask_generator import SamAutomaticMaskGenerator
        if not getattr(ResizeLongestSide, "_lwrclpy_float32_patch", False):
            def apply_coords_float32(self, coords, original_size):
                old_h, old_w = original_size
                new_h, new_w = self.get_preprocess_shape(original_size[0], original_size[1], self.target_length)
                coords = deepcopy(coords).astype(np.float32)
                coords[..., 0] = coords[..., 0] * np.float32(new_w / old_w)
                coords[..., 1] = coords[..., 1] * np.float32(new_h / old_h)
                return coords
            def apply_boxes_float32(self, boxes, original_size):
                boxes = apply_coords_float32(self, boxes.reshape(-1, 2, 2), original_size)
                return boxes.reshape(-1, 4)
            ResizeLongestSide.apply_coords = apply_coords_float32
            ResizeLongestSide.apply_boxes = apply_boxes_float32
            ResizeLongestSide._lwrclpy_float32_patch = True
        if not getattr(SamAutomaticMaskGenerator, "_lwrclpy_float32_patch", False):
            original_process_batch = SamAutomaticMaskGenerator._process_batch
            def process_batch_float32(self, points, im_size, crop_box, orig_size):
                points = np.asarray(points, dtype=np.float32)
                return original_process_batch(self, points, im_size, crop_box, orig_size)
            SamAutomaticMaskGenerator._process_batch = process_batch_float32
            SamAutomaticMaskGenerator._lwrclpy_float32_patch = True
    except Exception as exc:
        print("SAM float32 patch skipped:", exc)


def resolve_sam_checkpoint(state, checkpoint, model_type="vit_b"):
    requested = str(checkpoint or "").strip()
    model_key = str(model_type or "vit_b")
    default_name, url = SAM_CHECKPOINTS.get(model_key, SAM_CHECKPOINTS["vit_b"])
    if not requested:
        requested = default_name
    path = Path(requested).expanduser()
    if path.exists():
        return path
    if path.name not in {item[0] for item in SAM_CHECKPOINTS.values()}:
        raise FileNotFoundError("SAM checkpoint not found: " + str(path))
    try:
        hub_dir = Path(torch.hub.get_dir()) if torch is not None else Path.home() / ".cache" / "torch" / "hub"
    except Exception:
        hub_dir = Path.home() / ".cache" / "torch" / "hub"
    cache_path = hub_dir / "checkpoints" / path.name
    if cache_path.exists():
        return cache_path
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    if not state.get("sam_download_logged"):
        state["sam_download_logged"] = True
        print("Downloading SAM checkpoint:", url)
    tmp_path = cache_path.with_suffix(cache_path.suffix + ".download")
    urllib.request.urlretrieve(url, tmp_path)
    tmp_path.replace(cache_path)
    return cache_path


def sam_generator(state, checkpoint, model_type="vit_b", prefer_device="auto"):
    checkpoint_path = resolve_sam_checkpoint(state, checkpoint, model_type)
    key = "sam:" + str(model_type) + ":" + str(checkpoint_path) + ":" + str(prefer_device)
    generator = state.get(key)
    if generator is not None:
        return generator
    from segment_anything import SamAutomaticMaskGenerator, sam_model_registry
    patch_segment_anything_float32()
    device = select_torch_device(prefer_device)
    sam = sam_model_registry[str(model_type)](checkpoint=str(checkpoint_path))
    sam.to(device=device)
    generator = SamAutomaticMaskGenerator(sam)
    state[key] = generator
    if not state.get("device_logged"):
        state["device_logged"] = True
        print("SAM device:", device)
    return generator


def sam_mask_overlay(state, img, checkpoint="sam_vit_b_01ec64.pth", model_type="vit_b", prefer_device="auto"):
    bgr = ros_image_to_bgr(img)
    if bgr is None:
        return None
    rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    try:
        generator = sam_generator(state, checkpoint, model_type, prefer_device)
        masks = generator.generate(rgb)
    except Exception as exc:
        if str(prefer_device or "auto").lower() == "cpu":
            raise
        if not state.get("sam_cpu_fallback_logged"):
            state["sam_cpu_fallback_logged"] = True
            print("SAM device fallback to cpu:", exc)
        generator = sam_generator(state, checkpoint, model_type, "cpu")
        masks = generator.generate(rgb)
    overlay = bgr.copy()
    rng = np.random.default_rng(12345)
    for item in sorted(masks, key=lambda m: int(m.get("area") or 0), reverse=True)[:24]:
        mask = item.get("segmentation")
        if mask is None:
            continue
        color = rng.integers(0, 255, size=3, dtype=np.uint8)
        overlay[mask] = (overlay[mask] * 0.45 + color * 0.55).astype(np.uint8)
    return bgr_to_ros_image(overlay)

