def midas_bundle(state, model_type="DPT_Hybrid", prefer_device="auto"):
    key = "midas:" + str(model_type) + ":" + str(prefer_device)
    bundle = state.get(key)
    if bundle is not None:
        return bundle
    if torch is None:
        raise RuntimeError("torch is required for MiDaS")
    device_name = select_torch_device(prefer_device)
    device = torch.device(device_name if device_name != "mps" else "mps")
    model = torch.hub.load("intel-isl/MiDaS", model_type, trust_repo=True)
    model.to(device).eval()
    transforms = torch.hub.load("intel-isl/MiDaS", "transforms", trust_repo=True)
    transform = transforms.dpt_transform if model_type.startswith("DPT") else transforms.small_transform
    state[key] = (model, transform, device)
    if not state.get("device_logged"):
        state["device_logged"] = True
        print("MiDaS device:", device_name)
    return state[key]


def midas_depth_overlay(state, img, model_type="DPT_Hybrid", prefer_device="auto"):
    bgr = ros_image_to_bgr(img)
    if bgr is None:
        return None
    rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    model, transform, device = midas_bundle(state, model_type, prefer_device)
    input_batch = transform(rgb).to(device)
    with torch.no_grad():
        prediction = model(input_batch)
        prediction = torch.nn.functional.interpolate(
            prediction.unsqueeze(1),
            size=rgb.shape[:2],
            mode="bicubic",
            align_corners=False,
        ).squeeze()
    depth = prediction.detach().cpu().numpy()
    norm = cv2.normalize(depth, None, 0, 255, cv2.NORM_MINMAX).astype(np.uint8)
    color = cv2.applyColorMap(norm, cv2.COLORMAP_INFERNO)
    return bgr_to_ros_image(color)
